for (f in sort(list.files('R', pattern='[.]R$', full.names=TRUE))) sys.source(f, .GlobalEnv)
repo <- getwd(); ticket <- normalizePath('inst/examples/tickets/D-T01.yaml', winslash='/', mustWork=TRUE)
root <- tempfile('d-t01-paired-cli-probe-', tmpdir='/private/tmp'); dir.create(file.path(root,'tickets'),recursive=TRUE); dir.create(file.path(root,'data'),recursive=TRUE)
file.copy(ticket,file.path(root,'tickets'),overwrite=TRUE)
file.copy(list.files('inst/examples/data', full.names=TRUE), file.path(root,'data'), recursive=TRUE)
config <- file.path(root,'tickets','D-T01.yaml'); metadata_path <- file.path(root,'data','c04','metadata.tsv')
metadata <- utils::read.delim(metadata_path,check.names=FALSE,stringsAsFactors=FALSE); metadata$subject <- rep(paste0('sub',1:6),each=2); metadata$visit <- rep(c('baseline','followup'),times=6); utils::write.table(metadata,metadata_path,sep='\t',row.names=FALSE,quote=FALSE)
text <- readLines(config,warn=FALSE)
text <- sub('  subject_id: null','  subject_id: subject',text,fixed=TRUE)
text <- sub('    score: numeric','    score: numeric\n    subject: string\n    visit: factor\n    time: numeric',text,fixed=TRUE)
text <- sub('  factor_levels: {}','  factor_levels:\n    visit: [baseline, followup]',text,fixed=TRUE)
text <- sub('      kind: independent','      kind: paired',text,fixed=TRUE)
text <- sub('      condition: score','      condition: visit',text,fixed=TRUE)
text <- sub('      condition_type: continuous','      condition_type: factor',text,fixed=TRUE)
text <- sub('      condition_type: continuous','      condition_type: continuous',text,fixed=TRUE)
text <- sub('      subject_id: null','      subject_id: subject',text,fixed=TRUE)
text <- sub('      repeated: false','      repeated: true',text,fixed=TRUE)
text <- sub('      representation: levels','      representation: delta',text,fixed=TRUE)
text <- sub('      reference_level: null','      reference_level: baseline',text,fixed=TRUE)
text <- sub('      target_level: null','      target_level: followup',text,fixed=TRUE)
text <- sub('      between_group: null','      between_group: null',text,fixed=TRUE)
text <- sub('      visit_column: null','      visit_column: visit',text,fixed=TRUE)
text <- sub('      reference_visit: null','      reference_visit: baseline',text,fixed=TRUE)
text <- sub('      target_visit: null','      target_visit: followup',text,fixed=TRUE)



text <- sub('        - contrast_id: score_slope','        - contrast_id: target_minus_reference',text,fixed=TRUE)
text <- sub('          weights: {intercept: 0, continuous.score: 1}','          weights: {intercept: 1}',text,fixed=TRUE)
text <- sub('      effect_unit: per_unit_beta','      effect_unit: delta_difference',text,fixed=TRUE)
writeLines(text,config,useBytes=TRUE)
cv<-triomics_read_config(config); ing<-triomics_ingest_configured_study(cv,config); aa<-cv$analyses[[1]]; st<-list(study_id=cv$study_id,preparation_context_id=aa$preparation_context_id,sample_metadata=ing$sample_metadata,sample_registry=ing$sample_registry,declared_factor_levels=ing$declared_factor_levels,feature_registry=ing$feature_registry,assays=ing$assays[unlist(aa$block_ids)],assay_hashes=NULL,analysis_unit_map=NULL); rr<-tryCatch(triomics_resolve_analysis(st,aa),error=identity); if(inherits(rr,'error')) cat('RESOLVE_ERROR=',conditionMessage(rr),'\n') else { cat('COLS=',paste(rr$model_plan$column_ids,collapse=','),'\n'); if ('time.linear' %in% rr$model_plan$column_ids) { w<-as.list(stats::setNames(rep(0,length(rr$model_plan$column_ids)),rr$model_plan$column_ids)); w[['time.linear']]<-1; aa$statistics$contrasts[[1]]$weights<-w; cv$analyses[[1]]<-aa; jsonlite::write_json(cv,config,auto_unbox=TRUE,pretty=TRUE,null='null',digits=NA) } }
cli <- normalizePath(file.path(repo,'exec','triomics'),winslash='/',mustWork=TRUE)
run <- function(stage) { previous<-setwd(dirname(cli)); on.exit(setwd(previous)); o<-system2(file.path(R.home('bin'),'Rscript'),c('--vanilla',shQuote(basename(cli)),'--config',shQuote(config),'--stage',shQuote(stage),'--output',shQuote(file.path(root,'out'))),stdout=TRUE,stderr=TRUE); s<-attr(o,'status'); if(is.null(s)) s<-0L; cat(stage,'STATUS',s,'\n',paste(o,collapse='\n'),'\n'); as.integer(s) }
b<-run('B'); if(b==0L) c<-run('C'); if(b==0L && c==0L) d<-run('D'); cat('ROOT=',root,'\n')
